def params_analysis(filter_type, value, value_params):
    """
    对向导式筛选条件对应入参目标值信息流进行解析，并返回包含筛选条件、指标数据、解析后的入参目标值
    """
    if filter_type in ('up_v', 'down_v'):
        try:
            value = value[-1]
        except:
            value = value
    elif filter_type == 'region_v':
        try:
            value = value[-1]
        except:
            value = value
        value_params = value_params.split(',')
        return {'filter_type': filter_type, 'value': value, 'ob_start_value': float(value_params[0]), 'ob_end_value': float(value_params[1])}
    elif filter_type in ('up_mean', 'down_mean'):
        return {'filter_type': filter_type, 'value_array': value, 'ob_days': int(value_params)}
    elif filter_type == 'region_mean':
        value_params = value_params.split(',')
        return {'filter_type': filter_type, 'value_array': value, 'ob_days_start': int(value_params[0]), 'ob_days_end': int(value_params[1])}
    elif filter_type in ('golden_cross', 'death_cross', 'long_status', 'short_status'):
        return {'filter_type': filter_type, 'short_values': value[0], 'long_values': value[1]}
    elif filter_type in ('up_status', 'down_status'):
        return {'filter_type': filter_type, 'value': value[0], 'ob_value': value[1]}
    else:
        return {'filter_type': filter_type, 'value': value}
