def up_mean_desicion(value_array, days_value):
    """
    大于均值条件决策
    """
    if value_array[-1] > np.mean(value_array[-days_value:]):
        return True
    else:
        return False
def down_mean_desicion(value_array, days_value):
    """
    小于条件决策
    """
    if value_array[-1] < np.mean(value_array[-days_value:]):
        return True
    else:
        return False
def region_mean_desicion(value_array, days_start, days_end):
    """
    均值区间条件决策
    """
    if len(value_array) < max(days_start, days_end):
        user_log.info('区间均值状态判断入参序列数据长度不足')
        return None
    elif np.mean(value_array[-days_start:]) <= value_array[-1] <= np.mean(value_array[-days_end:]):
        return True
    return False
