def get_DMI(high_data, low_data, close_data, n1, n2):
    """
    DMI计算
    """
    def calculate_di(high, low, pre_close):
        high_now = high[1:]
        low_now = low[1:]
        tr = sum((max(max(high_now[i] - low_now[i], abs(high_now[i] - pre_close[i])), abs(low_now[i] - pre_close[i])) for i in range(n1)))
        dmp = sum((high[-i] - high[-(i + 1)] if high[-i] - high[-(i + 1)] > 0 else 0 for i in range(1, n1 + 1)))
        dmm = sum((low[-(i + 1)] - low[-i] if low[-(i + 1)] - low[-i] > 0 else 0 for i in range(1, n1 + 1)))
        di1 = dmp * 100 / tr
        di2 = dmm * 100 / tr
        return (di1, di2)
    def calculate_adx(high, low, close):
        di_list = []
        for i in range(n2):
            if i == 0:
                d1, d2 = calculate_di(high[-(n1 + 1 + i):], low[-(n1 + 1 + i):], close[-(n1 + i + 1):-(1 + i)])
            else:
                d1, d2 = calculate_di(high[-(n1 + 1 + i):-i], low[-(n1 + 1 + i):-i], close[-(n1 + 1 + i):-(1 + i)])
            di_list.append((d1, d2))
        else:
            return sum((abs(d2 - d1) / (d1 + d2) * 100 for d1, d2 in di_list)) / n2
    pdi, mdi = calculate_di(high_data[-(n1 + 1):], low_data[-(n1 + 1):], close_data[-(n1 + 1):-1])
    adx = calculate_adx(high_data, low_data, close_data)
    adxr = (adx + calculate_adx(high_data[:-n2], low_data[:-n2], close_data[:-n2])) / 2
    return (pdi, mdi, adx, adxr)
