def get_rank_data(sort_info, factor_list, foctor_rank_list, factor_sort_type):
    df = pd.DataFrame.from_dict(sort_info)
    df.dropna(inplace=True)
    positive_reverse_factor_trans_list = []
    for factor in factor_list:
        if factor in POSITIVE_REVERSE_FACTOR_INFO:
            positive_reverse_factor_trans_list.append(factor)
    df = positive_reverse_factor_trans(df, positive_reverse_factor_trans_list)
    for factor in factor_list:
        sort_type = factor_sort_type[factor]
        if sort_type == 'positive':
            df[factor + '_rank'] = df[factor].rank(ascending=True, pct=True)
        elif sort_type == 'reverse':
            df[factor + '_rank'] = df[factor].rank(ascending=False, pct=True)
        foctor_rank_list.append(factor + '_rank')
    else:
        df = df[foctor_rank_list]
        df['all_rank'] = df.apply(lambda x: x.sum(), axis=1)
        df = df.sort_values(by='all_rank', ascending=False)
        return df
def float_replace(x, code_type='stock'):
    float_num = 2
    if code_type == 'stock':
        float_num = 2
    try:
        x = float(str(round(Decimal(x), float_num)))
    except BaseException:
        x = float(str(round(x, float_num)))
    return x
