        user_log.info('买入因子信息：')
        user_log.info(wizard_factor_buy_transac_config_info)
        user_log.info('卖出因子信息：')
        user_log.info(wizard_factor_sell_transac_config_info)
        user_log.info('定期调仓模式参数信息：')
        user_log.info(regular_trade_info)
        user_log.info('择时交易模式参数信息：')
        user_log.info(condition_trade_info)
        user_log.info('股票池参数信息：')
        user_log.info(security_pool_info)
        user_log.info('风控参数信息：')
        user_log.info(risk_config_info)
        user_log.info('风控参数控制信息：')
        user_log.info(risk_control_config_info)
        user_log.info('自选股信息：')
